  clases = {
    WARRIOR = {
      id = 1, porDefecto = 1,
      recomendadas = { fabricar = { 164, 186 }, oro = { 186, 182 }, pvp = { 202, 186 } },
      objetivos = {
        fabricar = { t = "Blacksmithing + Mining: te haces tus armas, tus Plate y las llaves de hierro.", por = "Plate y armas One-Hand y Two-Hand. Warrior y Paladin se hacen su propio equipo; el Shaman, sus Maces y Axes.", otras = { { "Engineering + Mining", "", "Utilidad para ti mismo: Guns y Scopes (Hunter), cascos, granadas, reflectores y Trinkets." }, { "Alchemy + Herbalism", "", "Consumibles propios: Mana Potions, Elixirs y Flasks para mazmorras y bandas." } } },
        oro = { t = "Mining + Herbalism (o Mining + Skinning) mientras subes; vendes todo en la casa de subastas.", por = "Las dos recolecciones: cero gasto, todo lo que recoges se vende en la casa de subastas. Lo mejor mientras subes de nivel y para juntar el oro de la montura.", otras = { { "Skinning + Mining", "Clases que matan bestias (Hunter, Rogue, Warrior)", "Sin cambiar de rastreo: desuellas lo que matas y picas lo que ves. Muy cómodo." }, { "Alchemy + Herbalism", "Cualquier clase (mejor a nivel 60)", "Potions, Elixirs y Flasks se consumen cada semana; los Transmutes tienen reutilización (23 h la mayoría, dato de la beta)." }, { "Enchanting + Tailoring", "Cloth (Priest, Mage, Warlock)", "Fabricas objetos verdes con tela barata, los desencantas y vendes Dust y Essence, además de cobrar por encantar." } } },
        pvp = { t = "Engineering + Mining: granadas, reflectores y cascos de ingeniería.", por = "Iron Grenade (aturdir), Reflectors, cascos con efectos, Net-o-Matic; es la profesión de PvP por excelencia.", otras = { { "Alchemy + Herbalism", "", "Swiftness Potion, Invisibility, Free Action Potion, Elixirs de Agility/Strength/Intellect y Mana Potions." }, { "Enchanting (+ Tailoring o Mining)", "", "Encantamientos de armas y de Stamina/velocidad para tu propio equipo." }, { "First Aid (secundaria, obligatoria)", "", "Bandages y, en Forever, Healing Potions y Anti-Venom: sin esto no se hace PvP." } } },
      },
      talentos = {
        ["Improved Heroic Strike"] = { 3, "Reduce 1/2/3 p. de ira el costo de tu facultad Heroic Strike.", "Arms", 1, 1, "ability_rogue_ambush", "", "Reduces the cost of your Heroic Strike ability by 1/2/3 Rage." },
        ["Deflection"] = { 5, "Aumenta tu probabilidad de parar un 1/2/3/4/5%.", "Arms", 1, 2, "ability_parry", "", "Increases your Parry chance by 1/2/3/4/5%." },
        ["Improved Rend"] = { 3, "Aumenta un 12/23/35% el daño de sangrado de tu facultad Rend.", "Arms", 1, 3, "ability_gouge", "", "Increases the Bleed damage done by your Rend ability by 12/23/35%." },
        ["Improved Charge"] = { 2, "Aumenta 3/6 p. la ira que genera tu facultad Charge.", "Arms", 2, 1, "ability_warrior_charge", "", "Increases the Rage generated by your Charge ability by 3/6." },
        ["Improved Tactical Mastery"] = { 3, "Tactical Mastery te permite retener hasta 5/10/15 p. más de tu ira cuando cambias de actitud.", "Arms", 2, 2, "spell_nature_enchantarmor", "", "Tactical Mastery lets you retain up to an additional 5/10/15 Rage when you change stances." },
        ["Improved Overpower"] = { 2, "Aumenta un 25/50% la probabilidad de golpe crítico de tu facultad Overpower.", "Arms", 2, 4, "inv_sword_05", "", "Increases the critical strike chance of your Overpower ability by 25/50%." },
        ["Anger Management"] = { 1, "Genera 1 p. de ira cada 3 s en combate y reduce un 30% la pérdida de ira fuera de combate.", "Arms", 3, 2, "spell_holy_blessingofstamina", "Improved Tactical Mastery", "Generates 1 Rage every 3 sec while in combat, and reduces Rage loss while out of combat by 30%." },
        ["Deep Wounds"] = { 3, "Tus golpes críticos hacen sangrar al enemigo e infligen un 20/40/60% del daño promedio de tu arma cuerpo a cuerpo durante 12 s.", "Arms", 3, 3, "ability_backstab", "Improved Rend", "Your critical strikes cause your opponent to Bleed, dealing 20/40/60% of your melee weapon's average damage over 12 sec." },
        ["Spearing Strike"] = { 1, "Un ataque violento que inflige un 75% de daño con arma. Inflige 75% p. más de daño con arma contra gigantes, dragonantes y objetivos montados. Estos últimos quedan desmontados.", "Arms", 4, 1, "inv_spear_01", "", "A brutal attack that deals 75% weapon damage. Deals an additional 75% weapon damage against Giants, Dragonkin, and mounted targets. Mounted targets are dismounted." },
        ["Two-Handed Weapon Specialization"] = { 3, "Aumenta un 2/4/6% el daño infligido con las armas cuerpo a cuerpo de dos manos.", "Arms", 4, 2, "inv_axe_09", "", "Increases the damage you deal with two-handed melee weapons by 2/4/6%." },
        ["Impale"] = { 2, "Aumenta un 10/20% el bonus de daño por golpe crítico de tus facultades.", "Arms", 4, 3, "ability_searingarrow", "Deep Wounds", "Increases the critical strike damage bonus of your abilities by 10/20%." },
        ["Bloodthrill"] = { 2, "Otorga un 10/20% de probabilidad de activar Overpower a tus ataques cuerpo a cuerpo con el arma de la mano derecha contra enemigos afectados por Desgarro.", "Arms", 5, 1, "inv_sword_01", "", "Grants your Main Hand melee attacks against enemies afflicted by your Rend a 10/20% chance to allow an activation of Overpower." },
        ["Sweeping Strikes"] = { 1, "Tus próximos 5 ataques cuerpo a cuerpo golpean a otro enemigo cercano.", "Arms", 5, 2, "ability_rogue_slicedice", "", "Your next 5 melee attacks strike an additional nearby opponent." },
        ["Weaponmaster"] = { 5, "Les otorga a tus ataques con armas cuerpo a cuerpo un beneficio según el tipo de arma.\n\n Hacha/arma de asta: Aumenta tu\n probabilidad de golpe crítico un 1/2/3/4/5%.\n\n Maza/bastón: Tus ataques ignoran\n un 3/6/9/12/15% de la armadura de tu objetivo.\n\n Espada: Los ataques cuerpo a cuerpo que asestes\n tienen un 1/2/3/4/5% de probabilidad de \n desencadenar un ataque extra sobre el \n objetivo.", "Arms", 5, 3, "garrison_weaponupgrade", "", "Gives your melee weapon attacks a benefit depending on the weapon.<br /><br /> <span style=\"color: #FFFFFF\">Axe/Polearm:</span> Increases your<br /> critical strike chance by 1/2/3/4/5%.<br /><br /> <span style=\"color: #FFFFFF\">Mace/Staff:</span> Your attacks ignore<br /> 3/6/9/12/15% of your target's armor.<br /><br /> <span style=\"color: #FFFFFF\">Sword:</span> Your successful melee <br /> attacks have a 1/2/3/4/5% chance to <br /> trigger an extra attack on the <br /> target." },
        ["Improved Slam"] = { 2, "Reduce 2.5/5.0 s el tiempo de reutilización de tu habilidad Slam y 0.25/0.50 s su tiempo de lanzamiento y el tiempo de reutilización global. Además, Slam ya no interrumpe ni demora tu golpe cuerpo a cuerpo.", "Arms", 6, 1, "ability_warrior_decisivestrike", "", "Reduces the cooldown of your Slam ability by 2.5/5.0 sec, the cast time and global cooldown by 0.25/0.50 sec, and Slam no longer interrupts or delays your melee swing." },
        ["Improved Hamstring"] = { 3, "Otorga a tu facultad Hamstring un 5/10/15% de probabilidad de inmovilizar al objetivo durante 5 s.", "Arms", 6, 3, "ability_shockwave", "", "Gives your Hamstring ability a 5/10/15% chance to immobilize the target for 5 sec." },
        ["Mortal Strike"] = { 1, "Un golpe sañoso que inflige daño con arma más 85 p., hiere al objetivo y reduce un 50% la efectividad de cualquier sanación durante 10 s.", "Arms", 7, 2, "ability_warrior_savageblow", "Sweeping Strikes", "A vicious strike that deals weapon damage plus 85 and wounds the target, reducing the effectiveness of any healing by 50% for 10 sec." },
        ["Booming Voice"] = { 5, "Aumenta un 10/20/30/40/50% el área de efecto de tus gritos y reduce un 5/10/15/20/25% su costo de ira de tus gritos y tus aullidos.", "Fury", 1, 2, "spell_nature_purge", "", "Increases the area of effect of your Shouts by 10/20/30/40/50% and reduces the Rage cost by of your Shouts and Howls by 5/10/15/20/25%." },
        ["Cruelty"] = { 5, "Mejora un 1/2/3/4/5% tu probabilidad de asestar un golpe crítico con ataques cuerpo a cuerpo.", "Fury", 1, 3, "ability_rogue_eviscerate", "", "Improves your chance to get a critical strike with melee attacks by 1/2/3/4/5%." },
        ["Lingering Rage"] = { 5, "Aumenta 2/4/6/8/10 s el tiempo que transcurre antes de que tu ira comience a disminuir después de salir de combate.", "Fury", 2, 2, "ability_warrior_secondwind", "", "Increases the time before your Rage begins to decay after leaving combat by 2/4/6/8/10 sec." },
        ["Unbridled Wrath"] = { 5, "Te otorga un 12/24/36/48/60% de probabilidad de generar 1 p. más de ira cuando infliges daño cuerpo a cuerpo con un arma.", "Fury", 2, 3, "spell_nature_stoneclawtotem", "", "Gives you a 12/24/36/48/60% chance to generate 1 additional Rage when you deal melee damage with a weapon." },
        ["Furious Precision"] = { 3, "Aumenta un 4/7/10% tu probabilidad de golpear con ataques de la mano izquierda.", "Fury", 3, 1, "ability_warrior_incite", "", "Increases your chance to hit with off-hand attacks by 4/7/10%." },
        ["Piercing Howl"] = { 1, "Provoca que todos los enemigos que están en un radio de 10 m queden Atontados y les reduce la velocidad de movimiento un 50% durante 6 s.", "Fury", 3, 2, "spell_shadow_deathscream", "", "Causes all enemies within 10 yds to be Dazed, reducing movement speed by 50% for 6 sec." },
        ["Blood Craze"] = { 3, "Regenera un 1/2/3% de tu salud total durante 6 s después de haber sufrido un golpe crítico o de perder más de un 20% de tu salud máxima con un solo ataque.", "Fury", 3, 3, "spell_shadow_summonimp", "", "Regenerates 1/2/3% of your total Health over 6 sec after being the victim of a critical strike or suffering more than 20% of your maximum Health from a single attack." },
        ["Enrage"] = { 5, "Te otorga un 30% de probabilidad de infligir un 2/4/6/8/10% más de daño Físico durante 12 s después de haber sufrido cualquier ataque dañino.", "Fury", 3, 4, "spell_shadow_unholyfrenzy", "", "Gives you a 30% chance to deal 2/4/6/8/10% increased Physical damage for 12 sec after being the victim of any damaging attack." },
        ["Dual Wield Specialization"] = { 5, "Aumenta un 5/10/15/20/25% el daño que inflige tu arma de mano izquierda y un 10/20/30/40/50% la ira que generas con los ataques con la mano izquierda.", "Fury", 4, 1, "ability_dualwield", "", "Increases the damage done by your off-hand weapon by 5/10/15/20/25% and the Rage generated by your off-hand attacks by 10/20/30/40/50%." },
        ["Reckless Swings"] = { 1, "Tus siguientes 4 ataques cuerpo a cuerpo generan 5 p. más de ira. Dura 8 s.", "Fury", 4, 2, "ability_warrior_bloodfrenzy", "", "Your next 4 melee attacks generate 5 additional Rage. Lasts 8 sec." },
        ["Improved Execute"] = { 2, "Reduce el costo de Ira de tu siguiente facultad Execute 3/5 p.", "Fury", 4, 4, "inv_sword_48", "", "Reduces the Rage cost of your Execute ability by 3/5." },
        ["Improved Berserker Rage"] = { 2, "Tu habilidad Berserker Rage generará instantáneamente 5/10 p. de ira y tiene un 50/100% de probabilidad de eliminar todos los efectos de reducción de movimiento cuando está activa.", "Fury", 5, 1, "spell_nature_ancestralguardian", "", "Your Berserker Rage ability will instantly generate 5/10 Rage and has a 50/100% chance to remove all movement impairing effects when activated." },
        ["Death Wish"] = { 1, "Cuando se activa, aumenta un 20% tu daño físico infligido y te vuelve inmune a los efectos de miedo, pero aumenta todo el daño recibido un 5%. Dura 30 s.", "Fury", 5, 2, "spell_shadow_deathpact", "", "When activated, increases your Physical damage done by 20% and makes you immune to Fear effects, but increases all damage you take by 5%. Lasts 30 sec." },
        ["Gore Drinker"] = { 2, "Tus habilidades Enrage, Berserker Rage, Bloodrage, Death Wish y Bloodthirst hacen que tus próximos 3 ataques cuerpo a cuerpo restauren 0.5/1.0% p. de tu salud máxima.", "Fury", 5, 3, "racial_troll_berserk", "Blood Craze", "Your Enrage, Berserker Rage, Bloodrage, Death Wish, and Bloodthirst abilities cause your next 3 melee attacks to restore 0.5/1.0% of your maximum Health." },
        ["Improved Intercept"] = { 2, "Reduce el tiempo de reutilización de tu facultad Intercept 5/10 s.", "Fury", 5, 4, "ability_rogue_sprint", "", "Reduces the cooldown of your Intercept ability by 5/10 sec." },
        ["Improved Whirlwind"] = { 2, "Reduce 1/2 s el tiempo de reutilización de tu habilidad Whirlwind y aumenta un 15/30% el daño que inflige al enemigo más cercano.", "Fury", 6, 1, "ability_whirlwind", "", "Reduces the cooldown of your Whirlwind ability by 1/2 sec and increases the damage it deals to the closest enemy by 15/30%." },
        ["Flurry"] = { 3, "Aumenta un 10/20/30% la velocidad de ataque cuerpo a cuerpo de tus 3 próximos golpes después de asestar un golpe crítico cuerpo a cuerpo.", "Fury", 6, 3, "ability_ghoulfrenzy", "", "Increases your melee attack speed by 10/20/30% for your next 3 swings after dealing a melee critical strike." },
        ["Bloodthirst"] = { 1, "Ataca de inmediato al objetivo, le inflige daño equivalente a un 45% de tu poder de ataque más 30 p. y aumenta un 10% tu velocidad de movimiento durante 10 s.", "Fury", 7, 2, "spell_nature_bloodlust", "Death Wish", "Instantly attack the target causing damage equal to 45% of your Attack Power plus 30 and increasing your movement speed by 10% for 10 sec." },
        ["Improved Bloodrage"] = { 2, "Aumenta un 25/50% toda la ira que genera tu facultad Bloodrage.", "Protection", 1, 1, "ability_racial_bloodrage", "", "Increases all the Rage generated by your Bloodrage ability by 25/50%." },
        ["Shield Specialization"] = { 5, "Aumenta un 1/2/3/4/5% tu probabilidad de bloquear ataques con tu escudo y te otorga una probabilidad del 20/40/60/80/100% de generar 5 p. de ira cuando bloqueas.", "Protection", 1, 2, "inv_shield_06", "", "Increases your chance to Block attacks with your shield by 1/2/3/4/5% and grants you a 20/40/60/80/100% chance to generate 5 Rage when you Block." },
        ["Iron Will"] = { 5, "Reduce un 3/6/9/12/15% la duración de los efectos de aturdimiento y miedo que te inflijan.", "Protection", 1, 3, "spell_magic_magearmor", "", "Reduces the duration of Stun and Fear effects inflicted on you by 3/6/9/12/15%." },
        ["Anticipation"] = { 5, "Aumenta 4/8/12/16/20 p. tu habilidad de defensa.", "Protection", 2, 1, "spell_nature_mirrorimage", "", "Increases your Defense Skill by 4/8/12/16/20." },
        ["Improved Revenge"] = { 3, "Aumenta un 20/40/60% el daño infligido por tu habilidad Revenge.", "Protection", 2, 3, "ability_warrior_revenge", "", "Increases damage dealt by your Revenge ability by 20/40/60%." },
        ["Improved Thunder Clap"] = { 3, "Reduce 2/4/6 p. el costo de ira de tu facultad Thunder Clap.", "Protection", 2, 4, "ability_thunderclap", "", "Reduces the Rage cost of your Thunder Clap ability by 2/4/6." },
        ["Last Stand"] = { 1, "Cuando se activa, esta habilidad te otorga temporalmente un 30% de tu salud máxima durante 20 s. Después de que el efecto expira, se pierde la salud.", "Protection", 3, 1, "spell_holy_ashestoashes", "", "When activated, this ability temporarily grants you 30% of your maximum health for 20 sec. After the effect expires, the health is lost." },
        ["Master of Defense"] = { 2, "Te otorga un 50/100% de probabilidad de generar 5 p. de ira cuando esquivas o paras mientras tienes un escudo equipado.", "Protection", 3, 2, "ability_warrior_shieldguard", "Shield Specialization", "Grants you a 50/100% chance to generate 5 Rage when you Dodge or Parry while a shield is equipped." },
        ["Improved Disarm"] = { 3, "Reduce 7/13/20 s el tiempo de reutilización de tu facultad Disarm.", "Protection", 3, 3, "ability_warrior_disarm", "", "Reduces the cooldown of your Disarm ability by 7/13/20 secs." },
        ["Defiance"] = { 3, "Cuando tienes equipado un escudo, aumenta un 5/10/15% más toda la amenaza generada en Defensive Stance.", "Protection", 3, 4, "ability_warrior_innerrage", "", "Increases all threat generated in Defensive stance by an additional 5/10/15% while a shield is equipped." },
        ["Improved Sunder Armor"] = { 3, "Reduce 1/2/3 p. el costo de ira de tu habilidad Sunder Armor.", "Protection", 4, 1, "ability_warrior_sunder", "", "Reduces the Rage cost of your Sunder Armor ability by 1/2/3." },
        ["Vanguard"] = { 1, "Ahora puedes usar tu habilidad Charge mientras estás en actitud defensiva.", "Protection", 4, 2, "ability_warrior_shieldcharge", "", "Your Charge ability is now usable while in Defensive Stance." },
        ["Improved Shield Bash"] = { 2, "Otorga a tu facultad Shield Bash un 50/100% de probabilidad de silenciar al objetivo durante 3 s.", "Protection", 4, 3, "ability_warrior_shieldbash", "", "Gives your Shield Bash ability a 50/100% chance to Silence the target for 3 sec." },
        ["Improved Shield Wall"] = { 2, "Reduce 5.5/11.0 min el tiempo de reutilización de tu habilidad Shield Wall.", "Protection", 5, 1, "ability_warrior_shieldwall", "", "Reduces the cooldown of your Shield Wall ability by 5.5/11.0 min." },
        ["Concussion Blow"] = { 1, "Aturde al objetivo durante 5 s.", "Protection", 5, 2, "ability_thunderbolt", "", "Stuns the target for 5 sec." },
        ["Focused Rage"] = { 3, "Reduce 1/2/3 p. el costo de ira de tus habilidades ofensivas.", "Protection", 5, 3, "ability_warrior_focusedrage", "", "Reduces the Rage cost of your offensive abilities by 1/2/3." },
        ["Bastion"] = { 5, "Aumenta un 2/4/6/8/10% todo el daño que infliges con un escudo equipado.", "Protection", 6, 3, "inv_shield_04", "", "Increases all damage you deal by 2/4/6/8/10% while a shield is equipped." },
        ["Shield Slam"] = { 1, "Embate al objetivo con tu escudo, le inflige 430 p. de daño que aumenta según tu valor de bloqueo y tiene un 50% de probabilidad de disipar 1 efecto mágico en el objetivo. Provoca una gran amenaza.", "Protection", 7, 2, "inv_shield_05", "Concussion Blow", "Slam the target with your shield, causing 421 to 439 damage, increased by your Block Value, and has a 50% chance of dispelling 1 magic effect on the target. Causes a very high amount of threat." },
      },
