          porque = { ["Improved Rend"] = { "Rend se aplica siempre al empezar cada combate, así que mejorarlo sube tu daño.", "Rend is applied at the start of every fight, so improving it raises your damage.", "Icy Veins" }, ["Deflection"] = { "Más probabilidad de parar: sobrevives mejor y ganas un poco de daño.", "More Parry chance: better survivability and a very small damage gain.", "Icy Veins" }, ["Improved Overpower"] = { "Sube un 50 % la probabilidad de crítico de Overpower.", "Boosts Overpower's crit chance by a massive 50%.", "Icy Veins" }, ["Improved Tactical Mastery"] = { "Se coge solo para llegar a Anger Management.", "Taken simply to reach Anger Management.", "Icy Veins" }, ["Deep Wounds"] = { "Un poco más de daño cada vez que haces crítico.", "A bit of extra damage whenever you crit.", "Icy Veins" }, ["Anger Management"] = { "Da 1 de Rage cada 3 s en combate y la Rage baja más lento fuera de él.", "Generates 1 Rage every 3 sec in combat and slows Rage decay between pulls.", "Icy Veins" }, ["Two-Handed Weapon Specialization"] = { "Aumento de daño pequeño pero constante con arma de dos manos.", "A minor but consistent damage increase with a two-handed weapon.", "Icy Veins" }, ["Spearing Strike"] = { "Por solo 15 de Rage sirve para gastar Rage sobrante y rematar.", "For only 15 Rage it works as a Rage dump and a finisher.", "Icy Veins" }, ["Sweeping Strikes"] = { "Copia tus 5 siguientes ataques a un segundo enemigo; ideal en mazmorras.", "Copies your next 5 attacks onto a second target; great for dungeons.", "Icy Veins" } }, porque2 = { ["Cruelty"] = { "+5 % de crítico cuerpo a cuerpo: más daño y más Rage.", "+5% melee Crit chance: more damage and more Rage generated.", "Icy Veins" }, ["Unbridled Wrath"] = { "Tus golpes a una mano pueden dar Rage extra, lo que más le falta al Fury al principio.", "One-handed attacks can generate extra Rage, Fury's biggest early limit.", "Icy Veins" }, ["Furious Precision"] = { "+10 % de golpe con la mano izquierda para compensar el castigo de llevar dos armas.", "+10% off-hand hit chance to offset the dual wield miss penalty.", "Icy Veins" }, ["Piercing Howl"] = { "Frena un 50 % a los enemigos cercanos: útil contra varios o para escapar.", "Slows nearby enemies by 50%: useful vs. several enemies or to escape.", "Icy Veins" }, ["Lingering Rage"] = { "Es solo un punto de relleno en esa fila.", "Just a filler point on that tier.", "Icy Veins" }, ["Dual Wield Specialization"] = { "La mejor opción de la fila: sube el daño y la Rage que ganas.", "Best option on the tier: increases both damage dealt and Rage gained.", "Icy Veins" }, ["Death Wish"] = { "El mejor talento del árbol: +20 % de daño físico durante 30 s.", "The best talent in the tree: +20% Physical damage for 30 sec.", "Icy Veins" } },
