          porque = { ["Improved Rend"] = { "Rend se aplica siempre al empezar cada combate, así que mejorarlo sube tu daño.", "Rend is applied at the start of every fight, so improving it raises your damage.", "Icy Veins" }, ["Deflection"] = { "Más probabilidad de parar: sobrevives mejor y ganas un poco de daño.", "More Parry chance: better survivability and a very small damage gain.", "Icy Veins" }, ["Improved Overpower"] = { "Sube un 50 % la probabilidad de crítico de Overpower.", "Boosts Overpower's crit chance by a massive 50%.", "Icy Veins" }, ["Improved Tactical Mastery"] = { "Se coge solo para llegar a Anger Management.", "Taken simply to reach Anger Management.", "Icy Veins" }, ["Deep Wounds"] = { "Un poco más de daño cada vez que haces crítico.", "A bit of extra damage whenever you crit.", "Icy Veins" }, ["Anger Management"] = { "Da 1 de Rage cada 3 s en combate y la Rage baja más lento fuera de él.", "Generates 1 Rage every 3 sec in combat and slows Rage decay between pulls.", "Icy Veins" }, ["Two-Handed Weapon Specialization"] = { "Aumento de daño pequeño pero constante con arma de dos manos.", "A minor but consistent damage increase with a two-handed weapon.", "Icy Veins" }, ["Spearing Strike"] = { "Por solo 15 de Rage sirve para gastar Rage sobrante y rematar.", "For only 15 Rage it works as a Rage dump and a finisher.", "Icy Veins" }, ["Sweeping Strikes"] = { "Copia tus 5 siguientes ataques a un segundo enemigo; ideal en mazmorras.", "Copies your next 5 attacks onto a second target; great for dungeons.", "Icy Veins" } }, porque2 = { ["Shield Specialization"] = { "Hace que Shield Block no gaste Rage neta; te quita la falta de Rage.", "Makes Shield Block rage-neutral; eases the lack of Rage.", "Wowhead" }, ["Improved Revenge"] = { "+60 % de daño a Revenge, tu golpe más fuerte y barato.", "+60% damage to Revenge, your hardest-hitting, cheapest ability.", "Icy Veins" }, ["Improved Thunder Clap"] = { "Con la poca Rage del principio, hace el juego mucho más fluido.", "With little Rage early on, it makes the gameplay much smoother.", "Wowhead" }, ["Master of Defense"] = { "Da 5 de Rage cada vez que esquivas o paras con escudo.", "Generates 5 Rage whenever you Dodge or Parry with a shield equipped.", "Icy Veins" }, ["Improved Bloodrage"] = { "Más Rage de Bloodrage; ayuda cuando tu crítico aún es bajo.", "More Rage from Bloodrage; helps while your crit chance is low.", "Icy Veins" }, ["Vanguard"] = { "Permite Charge en Defensive Stance sin perder tu Rage.", "Lets you Charge in Defensive Stance and keep your Rage.", "Icy Veins" }, ["Cruelty"] = { "+5 % de crítico cuerpo a cuerpo: más daño y más Rage.", "+5% melee Crit chance: more damage and more Rage generated.", "Icy Veins" }, ["Improved Rend"] = { "Sube mucho el daño de Rend.", "Greatly boosts Rend damage.", "Icy Veins" }, ["Defiance"] = { "Generas más amenaza: los mobs se quedan contigo.", "More threat generated: mobs stay on you.", "Wowhead" }, ["Last Stand"] = { "Opcional: a nivel 30 casi no hace falta, pero puedes cogerlo si te da seguridad.", "Optional: level 30 content rarely needs it, but take it if it makes you feel safer.", "Icy Veins" } },
