          porque = { ["Divine Intellect"] = { "2 % más de Intellect, que se acumula a niveles más altos.", "2% more Intellect, which you will stack at higher levels.", "Wowhead" }, ["Improved Seals"] = { "Más daño de Judgement y de todos tus Seals, sobre todo Seal of Righteousness.", "More damage on Judgement and all Seals, notably Seal of Righteousness.", "Icy Veins" }, ["Benediction"] = { "Ayuda con el maná para usar más hechizos durante más tiempo.", "Helps your Mana economy so you can use more spells for longer.", "Icy Veins" }, ["Improved Judgement"] = { "Más daño: puedes usar Judgement más veces.", "More damage by allowing more uses of Judgement.", "Icy Veins" }, ["Holy Conduit"] = { "Ayuda con el maná para usar más hechizos durante más tiempo.", "Helps your Mana economy so you can use more spells for longer.", "Icy Veins" }, ["Sanctified Judgement"] = { "Cada Judgement te devuelve maná.", "Every Judgement returns Mana.", "Wowhead" }, ["Seal of Command"] = { "Sello de mucho daño de arma para armas de dos manos lentas.", "Strong weapon damage seal for slow two-handers.", "Wowhead" }, ["Pursuit of Justice"] = { "Tu única forma de correr más rápido: clave para subir por el mundo.", "Your only way to move faster: huge for open-world leveling.", "Wowhead" }, ["Sacred Arbiter"] = { "Mantiene tus Judgement con Holy Strike y sube su daño.", "Keeps your Judgement debuffs up via Holy Strike and raises its damage.", "Wowhead" }, ["Vengeance"] = { "Tras un crítico, más daño Physical y Holy durante 30 s (hasta 3 veces).", "After a crit, more Physical and Holy damage for 30 s (stacks 3 times).", "Wowhead" } }, porque2 = { ["Divine Intellect"] = { "Más Intellect y más maná: aguantas mejor y bebes menos.", "More Intellect and a bigger mana pool, so you drink less often.", "Icy Veins" }, ["Healing Light"] = { "Son los primeros puntos que puedes coger para mejorar como sanador.", "The earliest points you can take to improve as a healer.", "Wowhead" }, ["Improved Seals"] = { "Un poco más de daño si usas mucho Judgement.", "A bit of extra damage if you cast Judgement often.", "Icy Veins" }, ["Reverence"] = { "Sigues regenerando maná mientras lanzas hechizos.", "Keeps your Mana regenerating while you cast.", "Icy Veins" }, ["Spiritual Focus"] = { "La opción habitual para sanar (casi igual que Improved Seals).", "The go-to pick for healing (nearly interchangeable with Improved Seals).", "Icy Veins" }, ["Illumination"] = { "Muy útil al principio, cuando el maná cuesta mucho y tienes poco Intellect.", "Very helpful early when mana costs are high and Intellect is low.", "Icy Veins" }, ["Holy Shock"] = { "Sanación instantánea que también sirve para atacar mientras haces misiones.", "Instant heal that also works offensively while questing.", "Wowhead" } },
