        pvp = { t = "Engineering + Mining: Guns, Scopes, granadas y reflectores.", por = "Iron Grenade (aturdir), Reflectors, cascos con efectos, Net-o-Matic; es la profesión de PvP por excelencia.", otras = { { "Alchemy + Herbalism", "", "Swiftness Potion, Invisibility, Free Action Potion, Elixirs de Agility/Strength/Intellect y Mana Potions." }, { "Enchanting (+ Tailoring o Mining)", "", "Encantamientos de armas y de Stamina/velocidad para tu propio equipo." }, { "First Aid (secundaria, obligatoria)", "", "Bandages y, en Forever, Healing Potions y Anti-Venom: sin esto no se hace PvP." } } },
