      talentos = {
        ["Deadly Aspects"] = { 5, "Mientras Aspect of the Hawk está activo, Auto Shot tiene un 2/4/6/8/10% de probabilidad de aumentar un 30% la velocidad de ataque a distancia durante 12 s. Mientras Aspect of the Beast está activo, todos los ataques automáticos cuerpo a cuerpo tienen un 2/4/6/8/10% de probabilidad de aumentar un 30% la velocidad de ataque cuerpo a cuerpo durante 12 s.", "Beast Mastery", 1, 2, "spell_nature_ravenform", "", "While Aspect of the Hawk is active, Auto Shot has a 2/4/6/8/10% chance of increasing ranged attack speed by 30% for 12 sec. While Aspect of the Beast is active, all melee auto attacks have a 2/4/6/8/10% chance of increasing melee attack speed by 30% for 12 sec." },
        ["Endurance Training"] = { 5, "Aumenta un 3/6/9/12/15% la salud y la armadura de tus mascotas.", "Beast Mastery", 1, 3, "spell_nature_reincarnation", "", "Increases the Health and Armor of your pets by 3/6/9/12/15%." },
        ["Focused Fire"] = { 2, "Aumenta un 1/2% todo el daño que infligen tú y tu mascota mientras está activa.", "Beast Mastery", 2, 1, "inv_weapon_crossbow_10", "", "Increases all damage you and your pet deal by 1/2% while your pet is active." },
        ["Improved Aspect of the Monkey"] = { 3, "Aumenta un 2/4/6% el bonus de esquivar de tu Aspect of the Monkey. Además, tu mascota obtiene un 50% del efecto de tu habilidad Aspect of the Monkey.", "Beast Mastery", 2, 2, "ability_hunter_aspectofthemonkey", "", "Increases the Dodge bonus of your Aspect of the Monkey by 2/4/6%. Additionally, your pet gains 50% of the effect of your Aspect of the Monkey ability." },
        ["Improved Revive Pet"] = { 2, "El tiempo de lanzamiento de Revive Pet se reduce 3/6 s, el costo de maná se reduce un 20/40% y aumenta un 15/30% la cantidad de salud con la que revive tu mascota.", "Beast Mastery", 2, 3, "ability_hunter_beastsoothe", "", "Revive Pet's casting time is reduced by 3/6 sec, mana cost is reduced by 20/40%, and increases the health your pet returns with by an additional 15/30%." },
        ["Pathfinding"] = { 2, "Aumenta un 3/6% el bonus de velocidad de tu Aspect of the Cheetah y de tu Aspect of the Pack.", "Beast Mastery", 3, 1, "ability_mount_jungletiger", "", "Increases the speed bonus of your Aspect of the Cheetah and Aspect of the Pack by 3/6%." },
        ["Bestial Swiftness"] = { 1, "Aumenta un 30% la velocidad de movimiento de tus mascotas.", "Beast Mastery", 3, 2, "ability_druid_dash", "", "Increases the movement speed of your pets by 30%." },
        ["Unleashed Fury"] = { 5, "Aumenta un 3/6/9/12/15% el daño que infligen tus mascotas y halcones.", "Beast Mastery", 3, 3, "ability_bullrush", "", "Increases the damage done by your pets and hawks by 3/6/9/12/15%." },
        ["Improved Mend Pet"] = { 2, "Otorga al hechizo Mend Pet un 15/50% de probabilidad de purificar 1 efecto de maldición, enfermedad, magia o veneno de tu mascota cada vez que sana y reduce un 10/20% el costo de maná.", "Beast Mastery", 4, 1, "ability_hunter_mendpet", "", "Gives your Mend Pet spell a 15/50% chance of cleansing 1 Curse, Disease, Magic, or Poison effect from your pet each time it heals and reduces the Mana cost by 10/20%." },
        ["Ferocity"] = { 5, "Aumenta un 2/4/6/8/10% la probabilidad de golpe crítico de tus mascotas y halcones.", "Beast Mastery", 4, 3, "inv_misc_monsterclaw_04", "", "Increases the critical strike chance of your pets and hawks by 2/4/6/8/10%." },
        ["Summon Hawk"] = { 1, "Ordena a un halcón que se lance en picada contra un enemigo objetivo, lo que inflige X p. de daño físico y continúa su ataque durante 18 s. Solo pueden estar activos 2 halcones a la vez. Summon Hawk comparte su tiempo de reutilización con Arcane Shot.", "Beast Mastery", 4, 4, "ability_hunter_animalhandler", "", "Command a hawk to dive-bomb your targeted enemy, dealing [32 / <span class=\"q2\">Ferocity</span>: <span class=\"q9\">48</span> / <span class=\"q2\">Unleashed Fury</span>: <span class=\"q9\">52</span> + (Ranged Attack Power * (0.05))] Physical damage and continuing its assault for 18 sec. Only 2 hawks can be active at once. Summon Hawk shares its cooldown with Arcane Shot." },
        ["Spirit Bond"] = { 2, "Mientras tu mascota está activa, tú y tu mascota regeneran un 1% de su salud total cada 10/5 s.", "Beast Mastery", 5, 1, "ability_druid_demoralizingroar", "", "While your pet is active, you and your pet will regenerate 1% of total health every 10/5 sec." },
        ["Intimidation"] = { 1, "Ordena a tu mascota que aturda al objetivo durante 3 s en su siguiente ataque con éxito, lo que también otorga un 100% más de probabilidad de golpe crítico. Genera una gran amenaza.", "Beast Mastery", 5, 2, "ability_devour", "Bestial Swiftness", "Command your pet to Stun the target for 3 sec on its next successful attack, which also gains 100% increased critical strike chance. Generates high threat." },
        ["Bestial Discipline"] = { 2, "Aumenta un 10/20% la regeneración de enfoque de tus mascotas y permite que un 25/50% de tu regeneración de maná continúe mientras lanzas hechizos.", "Beast Mastery", 5, 4, "spell_nature_abolishmagic", "", "Increases the Focus regeneration of your pets by 10/20% and allows 25/50% of your Mana regeneration to continue while casting." },
        ["Frenzy"] = { 5, "Otorga a tu mascota un 20/40/60/80/100% probabilidad de obtener un incremento del 30% en la velocidad de ataque durante 8 s después de asestar un golpe crítico.", "Beast Mastery", 6, 3, "inv_misc_monsterclaw_03", "Ferocity", "Gives your pet a 20/40/60/80/100% chance to gain a 30% attack speed increase for 8 sec after dealing a critical strike." },
        ["Bestial Wrath"] = { 1, "Tu mascota se enfurece e inflige un 50% más de daño durante 18 s. Mientras está enfurecida, la bestia no siente piedad, remordimiento ni miedo y no se detendrá a no ser que la maten.", "Beast Mastery", 7, 2, "ability_druid_ferociousbite", "Intimidation", "Send your pet into a rage causing 50% additional damage for 18 sec. While enraged, the beast does not feel pity or remorse or fear and it cannot be stopped unless killed." },
        ["Hawk Eye"] = { 3, "Aumenta 2/4/6 m el alcance de tus armas a distancia.", "Marksmanship", 1, 1, "ability_townwatch", "", "Increases the range of your ranged weapons by 2/4/6 yards." },
        ["Improved Concussive Shot"] = { 5, "Otorga a tu Concussive Shot un 4/8/12/16/20% de probabilidad de aturdir al objetivo durante 3 s.", "Marksmanship", 1, 2, "spell_frost_stun", "", "Gives your Concussive Shot a 4/8/12/16/20% chance to stun the target for 3 sec." },
        ["Lethal Attacks"] = { 5, "Aumenta un 1/2/3/4/5% tu probabilidad de golpe crítico con todos los ataques.", "Marksmanship", 1, 3, "ability_searingarrow", "", "Increases your critical strike chance with all attacks by 1/2/3/4/5%." },
        ["Improved Stings"] = { 3, "Aumenta un 6/13/20% el daño de la habilidad Serpent Sting, reduce 2/4/6 s el tiempo de reutilización de la habilidad Viper Sting y aumenta 15/30/45 s la duración de la habilidad Scorpid Sting.", "Marksmanship", 2, 1, "ability_hunter_quickshot", "", "Increases the damage of your Serpent Sting ability by 6/13/20%, reduces the cooldown of your Viper Sting ability by 2/4/6 sec, and increases the duration of your Scorpid Sting ability by 15/30/45 sec." },
        ["Efficiency"] = { 5, "Reduce un 3/6/9/12/15% el costo de maná de tus Disparos, Picaduras y de tus habilidades cuerpo a cuerpo.", "Marksmanship", 2, 2, "spell_frost_wizardmark", "", "Reduces the Mana cost of your Shots, Stings, and melee abilities by 3/6/9/12/15%." },
        ["Careful Aim"] = { 5, "Aumenta tu poder de ataque en un valor equivalente al 20/40/60/80/100% de tu intelecto.", "Marksmanship", 2, 3, "ability_hunter_zenarchery", "", "Increases your Attack Power by 20/40/60/80/100% of your Intellect." },
        ["Rapid Killing"] = { 2, "Reduce 1/2 min el tiempo de reutilización de tu habilidad Rapid Fire. Además, cuando matas a un enemigo que no es común o muere mientras está afligido por tu Serpent Sting, obtienes Muerte rápida y aumenta un 10/20% el daño de tu siguiente habilidad de Disparo durante 20 s.", "Marksmanship", 3, 1, "ability_hunter_rapidkilling", "", "Reduces the cooldown on your Rapid Fire ability by 1/2 min. In addition, when you kill a non-trivial enemy or it dies while afflicted by your Serpent Sting, you gain Rapid Killing, increasing the damage of your next Shot ability within 20 sec by 10/20%." },
        ["Improved Arcane Shot"] = { 5, "Reduce 0.3/0.6/0.9/1.2/1.5 s el tiempo de reutilización de tu Arcane Shot. No afecta al tiempo de reutilización de las habilidades que comparten tiempo de reutilización con Arcane Shot.", "Marksmanship", 3, 2, "ability_impalingbolt", "", "Reduces the cooldown of your Arcane Shot by 0.3/0.6/0.9/1.2/1.5 sec. Does not affect the cooldown of abilities which share a cooldown with Arcane Shot." },
        ["Lone Wolf"] = { 1, "Infliges un 20% más de daño con todos tus ataques cuando no tienes una mascota activa.", "Marksmanship", 3, 4, "ability_mount_whitedirewolf", "", "You deal 20% increased damage with all attacks while you do not have an active pet." },
        ["Trueshot Aura"] = { 1, "Aumenta 20 p. el poder de ataque a distancia de todos los miembros del grupo o banda en un radio de 45 m.", "Marksmanship", 4, 2, "ability_trueshot", "", "Increases the Ranged Attack Power of party or raid members within 45 yds by 20." },
        ["Mortal Shots"] = { 5, "Aumenta un 6/12/18/24/30% el bonus de daño de golpe crítico en todas las habilidades a distancia.", "Marksmanship", 4, 3, "ability_piercedamage", "Careful Aim", "Increases the critical strike damage bonus on all ranged abilities by 6/12/18/24/30%." },
        ["Rapid Recuperation"] = { 2, "Aplicar Serpent Sting a un objetivo permite que el 25/50% de tu regeneración de maná continúe mientras se lanza durante 15 s. Este efecto aumenta al 50/100% cuando se consume Muerte rápida.", "Marksmanship", 5, 1, "ability_hunter_rapidregeneration", "Rapid Killing", "Afflicting a target with Serpent Sting allows 25/50% of your Mana Regeneration to continue while casting for 15 sec, increased to 50/100% when Rapid Killing is consumed." },
        ["Barrage"] = { 3, "Aumenta un 5/10/15% el daño que infligen tus habilidades Multi-Shot, Aimed Shot y Volley.", "Marksmanship", 5, 3, "ability_upgrademoonglaive", "", "Increases the damage done by your Multi-Shot, Aimed Shot, and Volley abilities by 5/10/15%." },
        ["Scatter Shot"] = { 1, "Un disparo a corta distancia que inflige un 50% de daño con arma y desorienta al objetivo durante 4 s. Cualquier daño infligido con posterioridad anulará su efecto. Desactiva tu ataque al ser utilizado.", "Marksmanship", 5, 4, "ability_golemstormbolt", "", "A short-range shot that deals 50% weapon damage and disorients the target for 4 sec. Any damage caused will remove the effect. Turns off your attack when used." },
        ["Ranged Weapon Specialization"] = { 5, "Aumenta un 1/2/3/4/5% el daño infligido con las armas a distancia.", "Marksmanship", 6, 3, "inv_weapon_rifle_06", "", "Increases the damage you deal with ranged weapons by 1/2/3/4/5%." },
        ["Sniper Shot"] = { 1, "Un disparo de largo alcance que inflige daño a distancia más 320 p. y aumenta 10 m el alcance de tus siguientes 3 disparos durante 10 s.", "Marksmanship", 7, 2, "hunter_pvp_snipershot", "Trueshot Aura", "A long-range shot that deals ranged damage plus 320 and increases the range of your next 3 Shots by 10 yards for 10 sec." },
        ["Improved Tracking"] = { 5, "Mientras rastreas bestias, demonios, dragonantes, elementales, gigantes, humanoides o no-muertos, todo el daño que infliges al tipo de criatura rastreada aumenta un 1/2/3/4/5%.", "Survival", 1, 2, "inv_misc_head_dragon_black", "", "While tracking Beasts, Demons, Dragonkin, Elementals, Giants, Humanoids, or Undead, all damage you deal to the tracked creature type is increased by 1/2/3/4/5%." },
        ["Deflection"] = { 5, "Aumenta tu probabilidad de parar un 1/2/3/4/5%.", "Survival", 1, 3, "ability_parry", "", "Increases your Parry chance by 1/2/3/4/5%." },
        ["Entrapment"] = { 5, "Cuando tus trampas se activan, todos los objetivos afectados quedan Retenidos, lo que evita su movimiento durante 1/2/3/4/5 s.", "Survival", 2, 1, "spell_nature_stranglevines", "", "When your traps are triggered, all affected targets are Entrapped, preventing them from moving for 1/2/3/4/5 sec." },
        ["Savage Strikes"] = { 2, "Aumenta un 2/4% la probabilidad de golpe crítico de todas tus habilidades cuerpo a cuerpo.", "Survival", 2, 2, "ability_racial_bloodrage", "", "Increases the critical strike chance of all your melee abilities by 2/4%." },
        ["Survivalist"] = { 5, "Aumenta un 2/4/6/8/10% tu salud total.", "Survival", 2, 3, "spell_shadow_twilight", "", "Increases your total Health by 2/4/6/8/10%." },
        ["Improved Wing Clip"] = { 3, "Otorga a tu habilidad Wing Clip un 7/13/20% de probabilidad de inmovilizar al objetivo durante 5 s.", "Survival", 2, 4, "ability_rogue_trip", "", "Gives your Wing Clip ability a 7/13/20% chance to immobilize the target for 5 sec." },
        ["Clever Traps"] = { 2, "Aumenta un 15/30% la duración de los efectos de Freezing Trap y Frost Trap, y un 15/30% el daño de los efectos de Inmolación y Explosive Trap.", "Survival", 3, 1, "spell_nature_timestop", "", "Increases the duration of Freezing and Frost trap effects by 15/30% and the damage of Immolation and Explosive trap effects by 15/30%." },
        ["Surefooted"] = { 3, "Aumenta un 1/2/3% tu probabilidad de golpe y reduce un 10/20/30% la duración de los efectos de reducción de movimiento que sufres.", "Survival", 3, 2, "ability_kick", "", "Increases your hit chance by 1/2/3% and reduces the duration of movement impairing effects on you by 10/20/30%." },
        ["Deterrence"] = { 1, "Cuando se activa, aumenta la probabilidad de esquivar y de parar un 25% durante 10 s.", "Survival", 3, 3, "ability_whirlwind", "", "When activated, increases your Dodge and Parry chance by 25% for 10 sec.<!--cooldown:1310496:3 min cooldown-->" },
        ["Survival Tactics"] = { 2, "Aumenta un 5/10% la probabilidad de golpear con tus habilidades Trampa y Feign Death.", "Survival", 4, 1, "ability_ensnare", "", "Increases your chance to hit with your Trap and Feign Death abilities by 5/10%." },
        ["Predator's Edge"] = { 5, "Aumenta un 6/12/18/24/30% el daño de golpe crítico de habilidades cuerpo a cuerpo y un 10/20/30/40/50% el daño con arma de mano izquierda.", "Survival", 4, 2, "ability_dualwield", "", "Increases your melee ability critical strike damage by 6/12/18/24/30% and your Off Hand weapon damage by 10/20/30/40/50%." },
        ["Counterattack"] = { 1, "Un golpe que se activa tras parar el ataque de un oponente. Este ataque inflige un 50% de daño con arma más 26 p. e inmoviliza al objetivo durante 5 s. El contraataque no se puede bloquear, esquivar ni parar.", "Survival", 4, 3, "ability_warrior_challange", "Deterrence", "A strike that becomes active after parrying an opponent's attack. This attack deals 50% weapon damage plus 26 and immobilizes the target for 5 sec. Counterattack cannot be blocked, dodged, or parried." },
        ["Resourcefulness"] = { 2, "Reduce un 30/60% el costo de maná de tus habilidades Trampa y cuerpo a cuerpo, y otorga a tus golpes críticos de habilidades cuerpo a cuerpo o a distancia una probabilidad del 50/100% de permitir que el 50% de tu regeneración de maná continúe mientras se lanza durante 30 s.", "Survival", 5, 1, "ability_hunter_resourcefulness", "", "Reduces the Mana cost of your Trap and melee abilities by 30/60%, and grants your melee and ranged ability Critical Strikes a 50/100% chance to allow 50% of your Mana Regeneration to continue while casting for 30 sec." },
        ["Expose Prey"] = { 2, "Otorga un 5/10% de probabilidad de activar Mongoose Bite a tus ataques cuerpo a cuerpo y a distancia contra enemigos afectados por Hunter's Mark. Dura 10 s.", "Survival", 5, 2, "ability_hunter_swiftstrike", "", "Grants your melee and ranged attacks against enemies afflicted by Hunter's Mark a 5/10% chance to allow an activation of Mongoose Bite. Lasts 10 sec." },
        ["Survivalist's Discipline"] = { 2, "Reduce un 20/40% el tiempo de reutilización de tus habilidades Trampa y Deterrence.", "Survival", 5, 3, "ability_hunter_mastertactitian", "", "Reduces the cooldown of your Trap and Deterrence abilities by 20/40%." },
        ["Strider Kick"] = { 1, "Una patada potente que inflige un 100% del daño del arma cuerpo a cuerpo y aumenta un 30% la velocidad de movimiento durante 3 s.", "Survival", 5, 4, "ability_hunter_pet_tallstrider", "", "A powerful kick that deals 100% melee weapon damage and increases movement speed by 30% for 3 sec." },
        ["Lightning Reflexes"] = { 5, "Aumenta tu agilidad un 3/6/9/12/15%.", "Survival", 6, 3, "spell_nature_invisibilty", "", "Increases your Agility by 3/6/9/12/15%." },
        ["Lacerating Strikes"] = { 1, "Tu habilidad Mongoose Bite también provoca que el objetivo sangre, lo que inflige daño equivalente a un 40% del daño infligido con Mongoose Bite durante 21 s.", "Survival", 7, 2, "ability_gouge", "Expose Prey", "Your Mongoose Bite also causes the target to Bleed for damage equal to 40% of the damage done by Mongoose Bite over 21 sec" },
      },
