          porque = { ["Improved Sinister Strike"] = { "Abarata Sinister Strike, tu golpe más usado, para generar combo points más rápido.", "Cheaper Sinister Strike, your most used ability, so you build combo points faster.", "Icy Veins" }, ["Improved Eviscerate"] = { "Más daño de Eviscerate, tu remate principal: acabas antes con el objetivo.", "More Eviscerate damage, your main finisher, so you kill targets faster.", "Icy Veins" }, ["Deflection"] = { "Algo de parry al subir, pero sobre todo desbloquea Riposte.", "Some parry while leveling, but mainly it unlocks Riposte.", "Icy Veins" }, ["Precision"] = { "Más probabilidad de acertar; fallar es la mayor pérdida de daño.", "More hit chance; reducing misses is the biggest way to raise your damage.", "Icy Veins" }, ["Riposte"] = { "Gran aumento de daño; úsalo cada vez que se active al hacer parry.", "A massive damage increase; use it whenever it lights up after a parry.", "Icy Veins" }, ["Endurance"] = { "Baja mucho el cooldown de Sprint y Evasion: te mueves mejor y aguantas más.", "Greatly lowers Sprint and Evasion cooldowns for easier movement and mitigation.", "Icy Veins" }, ["Flawless Execution"] = { "Eviscerate cuesta menos energía y la gastas en generar más combo points.", "Eviscerate costs less energy, leaving more energy to build combo points.", "Icy Veins" }, ["Dual Wield Specialization"] = { "Más daño con el arma de la mano izquierda (off-hand).", "Increases the damage done by your off-hand weapon.", "Icy Veins" }, ["Blade Flurry"] = { "Daño a un objetivo extra y más velocidad de ataque; el Rogue sufre en AoE.", "Hits an extra target and raises attack speed; Rogue struggles with AoE.", "Icy Veins" } },
