          porque = { ["Improved Sinister Strike"] = { "Abarata Sinister Strike, tu golpe más usado, para generar combo points más rápido.", "Cheaper Sinister Strike, your most used ability, so you build combo points faster.", "Icy Veins" }, ["Improved Eviscerate"] = { "Más daño de Eviscerate, tu remate principal: acabas antes con el objetivo.", "More Eviscerate damage, your main finisher, so you kill targets faster.", "Icy Veins" }, ["Deflection"] = { "Algo de parry al subir, pero sobre todo desbloquea Riposte.", "Some parry while leveling, but mainly it unlocks Riposte.", "Icy Veins" }, ["Precision"] = { "Más probabilidad de acertar; fallar es la mayor pérdida de daño.", "More hit chance; reducing misses is the biggest way to raise your damage.", "Icy Veins" }, ["Riposte"] = { "Gran aumento de daño; úsalo cada vez que se active al hacer parry.", "A massive damage increase; use it whenever it lights up after a parry.", "Icy Veins" }, ["Endurance"] = { "Baja mucho el cooldown de Sprint y Evasion: te mueves mejor y aguantas más.", "Greatly lowers Sprint and Evasion cooldowns for easier movement and mitigation.", "Icy Veins" }, ["Flawless Execution"] = { "Eviscerate cuesta menos energía y la gastas en generar más combo points.", "Eviscerate costs less energy, leaving more energy to build combo points.", "Icy Veins" }, ["Dual Wield Specialization"] = { "Más daño con el arma de la mano izquierda (off-hand).", "Increases the damage done by your off-hand weapon.", "Icy Veins" }, ["Blade Flurry"] = { "Daño a un objetivo extra y más velocidad de ataque; el Rogue sufre en AoE.", "Hits an extra target and raises attack speed; Rogue struggles with AoE.", "Icy Veins" } }, porque2 = { ["Remorseless Attacks"] = { "Tras matar, más Crit en tu siguiente golpe: premia encadenar enemigos.", "After a kill, more Crit on your next strike, rewarding chain pulling.", "Icy Veins" }, ["Malice"] = { "Más Crit sin condiciones; un crítico hace el doble de daño.", "A flat Crit chance increase; crits deal double damage.", "Icy Veins" }, ["Ruthlessness"] = { "Tus remates pueden dejar un combo point extra: más remates.", "Finishers can add an extra combo point, so you cast more finishers.", "Icy Veins" }, ["Relentless Strikes"] = { "Energía extra para más golpes, más combo points y más remates.", "Extra energy for more abilities, more combo points and more finishers.", "Icy Veins" }, ["Lethality"] = { "Más daño crítico de Sinister Strike, Backstab y Mutilate, casi todo tu daño.", "More crit damage on Sinister Strike, Backstab and Mutilate, most of your damage.", "Icy Veins" }, ["Cold Blood"] = { "Cooldown de daño: asegura un crítico en tu siguiente golpe; úsalo siempre.", "DPS cooldown that guarantees a crit on your next strike; use it on cooldown.", "Icy Veins" }, ["Improved Poisons"] = { "Tus venenos se aplican más a menudo y a veces no gastan cargas.", "Poisons apply more often and sometimes do not consume charges.", "Icy Veins" }, ["Mutilate"] = { "Tu nuevo generador: mucho daño, extra contra envenenados y 2 combo points.", "Your new builder: high damage, bonus vs poisoned targets, 2 combo points.", "Icy Veins" }, ["Murder"] = { "Puntos flexibles: valen si no peleas contra Humanoid o Giant.", "Flexible points: worth it if you are not facing Humanoids or Giants.", "Wowhead" } },
