          porque = { ["Improved Sinister Strike"] = { "Abarata Sinister Strike, tu golpe más usado, para generar combo points más rápido.", "Cheaper Sinister Strike, your most used ability, so you build combo points faster.", "Icy Veins" }, ["Improved Eviscerate"] = { "Más daño de Eviscerate, tu remate principal: acabas antes con el objetivo.", "More Eviscerate damage, your main finisher, so you kill targets faster.", "Icy Veins" }, ["Deflection"] = { "Algo de parry al subir, pero sobre todo desbloquea Riposte.", "Some parry while leveling, but mainly it unlocks Riposte.", "Icy Veins" }, ["Precision"] = { "Más probabilidad de acertar; fallar es la mayor pérdida de daño.", "More hit chance; reducing misses is the biggest way to raise your damage.", "Icy Veins" }, ["Riposte"] = { "Gran aumento de daño; úsalo cada vez que se active al hacer parry.", "A massive damage increase; use it whenever it lights up after a parry.", "Icy Veins" }, ["Endurance"] = { "Baja mucho el cooldown de Sprint y Evasion: te mueves mejor y aguantas más.", "Greatly lowers Sprint and Evasion cooldowns for easier movement and mitigation.", "Icy Veins" }, ["Flawless Execution"] = { "Eviscerate cuesta menos energía y la gastas en generar más combo points.", "Eviscerate costs less energy, leaving more energy to build combo points.", "Icy Veins" }, ["Dual Wield Specialization"] = { "Más daño con el arma de la mano izquierda (off-hand).", "Increases the damage done by your off-hand weapon.", "Icy Veins" }, ["Blade Flurry"] = { "Daño a un objetivo extra y más velocidad de ataque; el Rogue sufre en AoE.", "Hits an extra target and raises attack speed; Rogue struggles with AoE.", "Icy Veins" } }, porque2 = { ["Camouflage"] = { "Stealth con menos cooldown y menos penalización de velocidad al subir.", "Shorter Stealth cooldown and faster stealth movement make leveling smoother.", "Icy Veins" }, ["Improved Ambush"] = { "Ambush hace muchísimo daño desde Stealth: más de media vida del enemigo.", "Huge Ambush damage from Stealth, over half of most enemies' health.", "Icy Veins" }, ["Setup"] = { "Combo points extra al esquivar, sobre todo durante Evasion.", "Extra combo points when you dodge, especially during Evasion.", "Icy Veins" }, ["Ghostly Strike"] = { "Daño extra sin tener que estar a la espalda del enemigo.", "Extra damage with no positional requirement, unlike Backstab.", "Icy Veins" }, ["Hemorrhage"] = { "Mucho daño por poca energía y sin ir a la espalda: tu generador siempre.", "High damage for low energy, no positional need: your builder at all times.", "Icy Veins" }, ["Master of Deception"] = { "Útil si te descubren seguido en sigilo.", "Useful if you keep getting detected in stealth.", "Icy Veins" }, ["Elusiveness"] = { "Te deja volver a sigilo más seguido para abrir con Garrote barato.", "Lets you re-stealth more often to open with a cheap Garrote.", "Wowhead" } },
