          porque = { ["Thundering Strikes"] = { "Mucho Crit desde temprano y combina con talentos más abajo.", "Bulk Crit early, and synergizes with talents deeper in the tree.", "Icy Veins" }, ["Improved Ghost Wolf"] = { "Te mueves mucho más rápido por el mundo y ahora también en interiores.", "Much faster world travel, and now it also works indoors in dungeons.", "Icy Veins" }, ["Mental Dexterity"] = { "Intellect da Attack Power: más maná sin perder daño.", "Intellect gives Attack Power: more mana without losing offense.", "Icy Veins" }, ["Shamanistic Focus"] = { "Baja el enorme costo de maná de los Shocks en combate.", "Eases the massive mana cost of Shocks in combat.", "Icy Veins" }, ["Ancestral Knowledge"] = { "Un punto al nivel 24 solo para abrir camino a los talentos siguientes.", "One point at level 24 just for pathing to later talents.", "Icy Veins" }, ["Elemental Weapons"] = { "Imbues más potentes, clave al nivel 30 con Windfury Weapon.", "Stronger imbues, especially important at level 30 with Windfury Weapon.", "Icy Veins" }, ["Flurry"] = { "Tus críticos cuerpo a cuerpo aumentan la velocidad de ataque.", "Your melee crits increase your attack speed.", "Icy Veins" }, ["Stormstrike"] = { "Tu único golpe activo cuerpo a cuerpo; activa imbues y es un gran salto al 25.", "Your only active melee strike; triggers imbues, big power spike at 25.", "Icy Veins" }, ["Improved Stormstrike"] = { "Por fin algo de regeneración de maná en combate y reinicios de Stormstrike.", "Finally some in-combat mana regen and Stormstrike resets for solo power.", "Icy Veins" } }, porque2 = { ["Concussion"] = { "5 % más daño.", "5% more damage.", "Icy Veins" }, ["Call of Flame"] = { "15 % más daño de Flame Shock y Searing Totem; desde el parche del 15-oct, Flame Shock además dura 9 s más.", "15% more damage for Flame Shock and Searing Totem; since the Oct-15 patch, Flame Shock also lasts 9 sec longer.", "Icy Veins" }, ["Elemental Warding"] = { "Un poco de reducción de daño.", "A bit of damage reduction.", "Icy Veins" }, ["Elemental Focus"] = { "Gasto de maná un poco mejor.", "A slightly better mana economy.", "Icy Veins" }, ["Elemental Alacrity"] = { "Uno de los mejores talentos de daño a un solo objetivo.", "One of Elemental's best single target talents.", "Icy Veins" }, ["Eye of the Storm"] = { "Lanzas hechizos sin que los golpes te retrasen todo el rato.", "Lets you cast without being constantly pushed back.", "Icy Veins" }, ["Improved Healing Wave"] = { "Una sanación más rápida puede salvarte a ti o al grupo en un apuro.", "A quicker heal can save you or your party in a pinch.", "Wowhead" }, ["Mindfulness"] = { "Mejora tu manejo del maná.", "Improves your Mana management.", "Wowhead" }, ["Water Shield"] = { "Mejora tu manejo del maná.", "Improves your Mana management.", "Wowhead" }, ["Convection"] = { "Opcional: hechizos que cuestan menos maná.", "Optional: spells that cost less Mana.", "Icy Veins" } },
