] = { "Con Water Shield recuperas maná al hacer críticos.", "With Water Shield orbs, your crits give mana back.", "Icy Veins" }, ["Ancestral Healing"] = { "Tus curas críticas suben la armadura del objetivo.", "Your heal crits increase the armor of your healing targets.", "Icy Veins" }, ["Mana Tide Totem"] = { "Devuelve mucho maná al grupo, con cooldown largo.", "Restores a lot of mana to group members on a long cooldown.", "Icy Veins" }, ["Tidal Mastery"] = { "Más Crit.", "Extra critical strike.", "Icy Veins" }, ["Concussion"] = { "5 % más de daño en tus hechizos de ataque.", "5% more damage on your offensive spells.", "Icy Veins" }, ["Elemental Alacrity"] = { "De los mejores talentos de daño a un objetivo pasado el nivel 20.", "One of the best single-target talents past level 20.", "Icy Veins" }, ["Convection"] = { "Hechizos que cuestan menos maná.", "Spells that cost less Mana.", "Icy Veins" } },
