          porque = { ["Suppression"] = { "3 % más de Hit (casi no fallas) y 12 % menos amenaza; Hit es tu mejor stat.", "3% more Hit and 12% less threat; Hit is your best DPS stat below the cap.", "Icy Veins" }, ["Improved Corruption"] = { "Corruption se vuelve instantánea y hace 10 % más; la repartes en movimiento.", "Makes Corruption instant and 10% stronger, easy to spread while moving.", "Icy Veins" }, ["Improved Bane of Agony"] = { "10 % más daño de Bane of Agony, tu DoT principal en enemigos que duran.", "10% more Bane of Agony damage, your main DoT on long-lived enemies.", "Icy Veins" }, ["Nightfall"] = { "Tus DoT y drenajes pueden dejar tu siguiente Shadow Bolt instantáneo.", "Your DoTs and Drains can make your next Shadow Bolt instant cast.", "Icy Veins" }, ["Pandemic"] = { "100 % más daño crítico en tus DoT y drenajes, que ahora pueden ser críticos.", "+100% Crit damage bonus on your DoTs and Drains, which can now crit.", "Icy Veins" }, ["Siphon Life"] = { "Otro DoT para enemigos duros; flojo al principio, mejora con equipo y nivel.", "An extra DoT for harder enemies; weak early, scales with gear and level.", "Icy Veins" }, ["Grim Reach"] = { "Tus hechizos de Affliction llegan un 10/20 % más lejos (sustituye a Malediction desde el parche del 15-oct).", "Your Affliction spells reach 10/20% farther (replaces Malediction since the 15-Oct patch).", "Icy Veins" }, ["Improved Life Tap"] = { "Life Tap es tu fuente de maná; Drain Life te devuelve la vida.", "Life Tap is your main Mana source; Drain Life heals it back.", "Wowhead" } },
