          porque = { ["Ferocity"] = { "Mejora tu Rage (más Maul al subir) y baja el costo de Energy en Cat Form.", "Helps Rage economy for more Maul casts and lowers Energy costs in Cat Form.", "Icy Veins" }, ["Feral Swiftness"] = { "Mucha más velocidad en Cat Form y más Dodge en todas las formas.", "Sizable movement speed in Cat Form plus more Dodge chance in all forms.", "Icy Veins" }, ["Feral Instinct"] = { "Más daño de Swipe y mejora Prowl cuando tienes Cat Form.", "More Swipe damage and a better Prowl once Cat Form is unlocked.", "Icy Veins" }, ["Shredding Attacks"] = { "Abre el paso a Shifting Power y Primal Bite.", "Opens the way to Shifting Power and Primal Bite.", "Icy Veins" }, ["Savage Fury"] = { "Abre el paso a Shifting Power y Primal Bite.", "Opens the way to Shifting Power and Primal Bite.", "Icy Veins" }, ["Shifting Power"] = { "Cambia Mana por Energy en Cat Form.", "Lets you trade Mana for Energy while in Cat Form.", "Icy Veins" }, ["Primal Bite"] = { "Añade otro ataque a Bear Form.", "Adds an extra attack to your Bear Form toolkit.", "Icy Veins" }, ["Blood Frenzy"] = { "Más generación de recurso (Feral Charge es la opción de movilidad).", "More resource generation (Feral Charge is the mobility option).", "Icy Veins" }, ["Leader of the Pack"] = { "Tú y todo el grupo tienen 3 % más de probabilidad de golpe crítico.", "Gives you and your whole party 3% more Critical Strike chance.", "Icy Veins" } },
          guia = { fuente = "Icy Veins", url = "https://www.icy-veins.com/wow-forever/feral-druid-melee-dps-and-tank-pve-guide", hasta = 30, verificada = 30, fecha = "2026-10-31", desact = { fecha = "2026-11-04", build = "1.60.1.70790", arbol = true, toca = 1, total = 19, cambios = { { "Lacerate: talento NUEVO (fila 4, nivel 25)", "Lacerate: NEW talent (row 4, level 25)", true }, { "Furor: talento NUEVO (fila 1, nivel 10)", "Furor: NEW talent (row 1, level 10)" }, { "Predatory Discipline: talento NUEVO (fila 4, nivel 25)", "Predatory Discipline: NEW talent (row 4, level 25)" }, { "Primal Bite: pasa de la fila 4 a la 7 (nivel 40)", "Primal Bite: moved from row 4 to row 7 (level 40)" }, { "Primal Bite: ahora pide Leader of the Pack", "Primal Bite: now requires Leader of the Pack" }, { "Shifting Power: pasa de la fila 4 a la 7 (nivel 40)", "Shifting Power: moved from row 4 to row 7 (level 40)" }, { "Shifting Power: ahora pide Predatory Discipline", "Shifting Power: now requires Predatory Discipline" }, { "Heart of the Wild: ya no está en el árbol", "Heart of the Wild: removed from the tree" } } } },
