          porque = { ["Ferocity"] = { "Mejora tu Rage (más Maul al subir) y baja el costo de Energy en Cat Form.", "Helps Rage economy for more Maul casts and lowers Energy costs in Cat Form.", "Icy Veins" }, ["Feral Swiftness"] = { "Mucha más velocidad en Cat Form y más Dodge en todas las formas.", "Sizable movement speed in Cat Form plus more Dodge chance in all forms.", "Icy Veins" }, ["Feral Instinct"] = { "Más daño de Swipe y mejora Prowl cuando tienes Cat Form.", "More Swipe damage and a better Prowl once Cat Form is unlocked.", "Icy Veins" }, ["Shredding Attacks"] = { "Abre el paso a Shifting Power y Primal Bite.", "Opens the way to Shifting Power and Primal Bite.", "Icy Veins" }, ["Savage Fury"] = { "Abre el paso a Shifting Power y Primal Bite.", "Opens the way to Shifting Power and Primal Bite.", "Icy Veins" }, ["Shifting Power"] = { "Cambia Mana por Energy en Cat Form.", "Lets you trade Mana for Energy while in Cat Form.", "Icy Veins" }, ["Primal Bite"] = { "Añade otro ataque a Bear Form.", "Adds an extra attack to your Bear Form toolkit.", "Icy Veins" }, ["Blood Frenzy"] = { "Más generación de recurso (Feral Charge es la opción de movilidad).", "More resource generation (Feral Charge is the mobility option).", "Icy Veins" }, ["Leader of the Pack"] = { "Tú y todo el grupo tienen 3 % más de probabilidad de golpe crítico.", "Gives you and your whole party 3% more Critical Strike chance.", "Icy Veins" } }, porque2 = { ["Reflection"] = { "17 % de regeneración de Mana mientras lanzas, útil en peleas sin pausa.", "17% Mana regen while casting, useful when you cannot stop casting.", "Wowhead" }, ["Gift of Nature"] = { "Mejora todas tus sanaciones.", "Improves all of your heals.", "Wowhead" }, ["Gift of the Earthmother"] = { "Rejuvenation responde mucho más rápido.", "Makes Rejuvenation far more responsive.", "Icy Veins" }, ["Swiftmend"] = { "Para salvar a alguien en peligro al instante.", "Instantly pick up someone in danger.", "Wowhead" }, ["Nature's Swiftness"] = { "Si Swiftmend está en espera, Healing Touch instantáneo.", "If Swiftmend is on cooldown, an instant Healing Touch.", "Wowhead" } },
